function log(b, x){ if(b <= 0 || b === 1 || x <= 0) return NaN; return Math.log(x) / Math.log(b); }
function ln(x){ return Math.log(x); }
function log10(x){ return Math.log10(x); }
function antilog(b, y){ if(b <= 0) return NaN; return Math.pow(b, y); }
var EXPORTS = { log:log, ln:ln, log10:log10, antilog:antilog };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LogarithmForgePure = EXPORTS; }
